/// Dither thresholds for quantization: per-voxel offsets in [0, 1) when enabled, 0.5
/// (i.e. rounding) otherwise.
#[derive(Clone, Copy, Debug)]
pub struct DitherLut {
    enabled: bool,
}

impl DitherLut {
    /// Create a table; `enabled = false` makes every threshold 0.5.
    pub fn new(enabled: bool) -> Self {
        DitherLut { enabled }
    }
    /// Threshold for voxel `offset` of a leaf.
    #[inline]
    pub fn get(&self, offset: usize) -> f32 {
        if self.enabled {
            LUT[offset & 511]
        } else {
            0.5
        }
    }
}
